export default function OnboardingPage() {
  const router = useRouter();
  const [currentSlide, setCurrentSlide] = useState(0);
  const [direction, setDirection] = useState(1);

  const isLast = currentSlide === slides.length - 1;

  const goNext = useCallback(() => {
    if (isLast) {
      try {
        localStorage.setItem("onboarding_completed", "true");
      } catch {
        // storage unavailable
      }
      router.push("/profile");
      return;
    }
    setDirection(1);
    setCurrentSlide((s) => s + 1);
  }, [isLast, router]);

  const goBack = useCallback(() => {
    if (currentSlide > 0) {
      setDirection(-1);
      setCurrentSlide((s) => s - 1);
    }
  }, [currentSlide]);

  const skip = useCallback(() => {
    try {
      localStorage.setItem("onboarding_completed", "true");
    } catch {
      // storage unavailable
    }
    router.push("/profile");
  }, [router]);

  const slide = slides[currentSlide];

  return (
    <div className="relative flex min-h-dvh flex-col overflow-hidden bg-bg">
      <MeshGradient intensity="low" />

      {/* Skip button */}
      {!isLast && (
        <button
          onClick={skip}
          className="absolute right-4 top-4 z-10 rounded-full px-4 py-2 text-sm font-medium text-text-muted transition-colors hover:text-text"
        >
          Passer
        </button>
      )}

      {/* Slide content */}
      <div className="relative z-10 flex flex-1 flex-col items-center justify-center px-6">
        <AnimatePresence mode="wait" custom={direction}>
          <motion.div
            key={currentSlide}
            custom={direction}
            variants={slideVariants}
            initial="enter"
            animate="center"
            exit="exit"
            drag="x"
            dragConstraints={{ left: 0, right: 0 }}
            dragElastic={0.3}
            onDragEnd={(_, info) => {
              if (info.offset.x < -80) goNext();
              else if (info.offset.x > 80) goBack();
            }}
            className="flex w-full max-w-sm flex-col items-center gap-6 text-center"
          >
            <motion.h1
              className="font-display text-3xl font-bold gradient-text"
              variants={welcomeVariants.illustration}
              initial="hidden"
              animate="visible"
            >
              {slide.title}
            </motion.h1>
            <p className="text-base text-text-muted">{slide.subtitle}</p>
            <motion.div
              className="mt-4 w-full"
              variants={welcomeVariants.illustration}
              initial="hidden"
              animate="visible"
            >
              {slide.content}
            </motion.div>
          </motion.div>
        </AnimatePresence>
      </div>

      {/* Bottom section: dots + button */}
      <div className="relative z-10 flex flex-col items-center gap-6 px-6 pb-12">
        {/* Dot indicators */}
        <div className="flex gap-2">
          {slides.map((_, i) => (
            <motion.button
              key={i}
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ ...springs.snap, delay: i * 0.05 }}
              onClick={() => {
                setDirection(i > currentSlide ? 1 : -1);
                setCurrentSlide(i);
              }}
              className={`h-2 rounded-full transition-all duration-300 ${
                i === currentSlide
                  ? "w-6 bg-accent"
                  : "w-2 bg-border hover:bg-text-muted"
              }`}
              aria-label={`Aller au slide ${i + 1}`}
            />
          ))}
        </div>

        {/* CTA button â€” Magnetic + glow pulse */}
        <Magnetic as="div" strength={0.16} radius={120} className="w-full max-w-xs">
          <motion.button
            onClick={goNext}
            whileHover={{ y: -2 }}
            whileTap={{ scale: 0.95 }}
            transition={springs.snap}
            className="w-full rounded-2xl py-4 text-center text-base font-semibold text-white gradient-bg relative overflow-hidden"
            style={{
              boxShadow:
                "0 8px 30px rgba(139,92,246,0.35), 0 0 0 1px rgba(255,255,255,0.05) inset",
            }}
          >
            <motion.span
              className="absolute inset-0 rounded-2xl"
              style={{
                background:
                  "linear-gradient(120deg, transparent 30%, rgba(255,255,255,0.18) 50%, transparent 70%)",
              }}
              animate={{ x: ["-120%", "120%"] }}
              transition={{ duration: 2.5, repeat: Infinity, ease: "easeInOut", repeatDelay: 1 }}
            />
            <span className="relative z-10">{isLast ? "Commencer" : "Suivant"}</span>
          </motion.button>
        </Magnetic>
      </div>
    </div>
  );
}

