              src={s.avatar}
              alt={s.name}
              loading="lazy"
              decoding="async"
              initial={{ scale: 0 }}
              animate={{ scale: 1 }}
              transition={{ ...springs.elastic, delay: i * 0.05 }}
              className="w-7 h-7 rounded-full border-2 border-card object-cover shrink-0"
