// --- Live badge ---

function LiveBadge() {
  return (
    <motion.span
      className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold text-white bg-red-500"
      animate={{ scale: [1, 1.1, 1] }}
