"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { motion, AnimatePresence } from "motion/react";
import { springs, micro, ambient } from "@/lib/motion-design";
import PageHeader from "@/components/ui/PageHeader";

// â”€â”€â”€ Types â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
type VerifyMethod = "selfie" | "phone" | "social" | "video";
type SelfieStep = "instructions" | "camera" | "success";
type PhoneStep = "input" | "code" | "success";
type VideoStep = "instructions" | "smile" | "turn" | "verifying" | "success";

// â”€â”€â”€ Constants â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const POSES = [
  { label: "Peace sign", emoji: "âœŒï¸�", instruction: "Fais le signe de paix avec ta main" },
  { label: "Pouce en l'air", emoji: "ðŸ‘�", instruction: "Leve ton pouce devant la camera" },
];

const METHODS: { key: VerifyMethod; icon: string; title: string; subtitle: string }[] = [
  { key: "selfie", icon: "ðŸ“¸", title: "Selfie verification", subtitle: "Photo avec une pose specifique" },
  { key: "phone", icon: "ðŸ“±", title: "Verification telephone", subtitle: "Code SMS a 6 chiffres" },
  { key: "video", icon: "ðŸŽ¥", title: "Video verification", subtitle: "Liveness check en video" },
  { key: "social", icon: "ðŸ”—", title: "Reseaux sociaux", subtitle: "Connecte Instagram ou LinkedIn" },
];

const VIDEO_PROMPTS = [
  { step: "smile" as const, emoji: "ðŸ˜Š", instruction: "Souris a la camera", duration: 2500 },
  { step: "turn" as const, emoji: "ðŸ‘ˆ", instruction: "Tourne la tete a gauche", duration: 2500 },
];

// â”€â”€â”€ Variants â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const cardVariants = {
  hidden: { opacity: 0, y: 30, scale: 0.92 },
  visible: (i: number) => ({
    opacity: 1,
    y: 0,
    scale: 1,
    transition: { ...springs.elastic, delay: 0.15 + i * 0.1 },
  }),
  tap: { scale: 0.97, transition: springs.micro },
};

const stepVariants = {
  enter: { opacity: 0, x: 80, scale: 0.96 },
  center: {
    opacity: 1,
    x: 0,
    scale: 1,
    transition: { duration: 0.4, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] },
  },
  exit: {
    opacity: 0,
    x: -80,
    scale: 0.96,
    transition: { duration: 0.3, ease: [0.76, 0, 0.24, 1] as [number, number, number, number] },
  },
};

const digitVariants = {
  hidden: { opacity: 0, scale: 0.3 },
  visible: (i: number) => ({
    opacity: 1,
    scale: 1,
    transition: { ...springs.snap, delay: i * 0.06 },
  }),
};

const checkmarkVariants = {
  hidden: { pathLength: 0, opacity: 0 },
  visible: {
    pathLength: 1,
    opacity: 1,
    transition: { duration: 0.6, ease: [0.16, 1, 0.3, 1] as [number, number, number, number], delay: 0.2 },
  },
};

const celebrationVariants = {
  hidden: { scale: 0, opacity: 0 },
  visible: {
    scale: [0, 1.35, 0.9, 1.1, 1],
    opacity: 1,
    transition: { duration: 0.7, times: [0, 0.3, 0.5, 0.7, 1] },
  },
};

// â”€â”€â”€ Progress component â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function ProgressBar({ methods, completed }: { methods: VerifyMethod[]; completed: Set<VerifyMethod> }) {
  const total = methods.length;
  const done = methods.filter(m => completed.has(m)).length;

  return (
    <div className="mb-6">
      <div className="flex items-center justify-between mb-2">
        <span className="text-[11px] text-text-muted font-semibold uppercase tracking-wider">
          Progression
        </span>
        <span className="text-[11px] font-bold text-accent">{done}/{total}</span>
      </div>
      <div className="h-1.5 bg-border rounded-full overflow-hidden">
        <motion.div
          className="h-full rounded-full gradient-bg"
          initial={{ width: 0 }}
          animate={{ width: `${(done / total) * 100}%` }}
          transition={springs.heavy}
        />
      </div>
    </div>
  );
}

// â”€â”€â”€ Selfie verification â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function SelfieVerification({ onComplete }: { onComplete: () => void }) {
  const [step, setStep] = useState<SelfieStep>("instructions");
  const [selectedPose, setSelectedPose] = useState(0);

  return (
    <AnimatePresence mode="wait">
      {step === "instructions" && (
        <motion.div
          key="selfie-instructions"
