                  selectedPose === i
                    ? "border-accent bg-accent/8"
                    : "border-border bg-bg-card hover:border-accent/30"
                }`}
                whileTap={micro.tapScale}
              >
                <span className="text-[32px]">{pose.emoji}</span>
                <span className="text-[12px] font-semibold text-text">{pose.label}</span>
              </motion.button>
            ))}
          </div>

          <motion.button
