            Telephone verifie !
          </motion.p>
          <motion.p
            className="text-[13px] text-text-muted mb-6"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.6 }}
          >
            Ton numero a ete confirme
          </motion.p>
          <motion.button
            onClick={onComplete}
            className="gradient-bg text-white px-8 py-3 rounded-full text-[14px] font-semibold shadow-glow tap-target"
            whileTap={micro.tapScale}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.7 }}
          >
            Continuer
          </motion.button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// â”€â”€â”€ Video liveness verification â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function VideoLivenessVerification({ onComplete }: { onComplete: () => void }) {
  const [step, setStep] = useState<VideoStep>("instructions");
  const [promptIndex, setPromptIndex] = useState(0);

  useEffect(() => {
    if (step === "smile" || step === "turn") {
      const idx = step === "smile" ? 0 : 1;
      setPromptIndex(idx);
      const timer = setTimeout(() => {
        if (idx === 0) {
          setStep("turn");
        } else {
          setStep("verifying");
        }
      }, VIDEO_PROMPTS[idx].duration);
      return () => clearTimeout(timer);
    }
    if (step === "verifying") {
      const timer = setTimeout(() => setStep("success"), 2000);
      return () => clearTimeout(timer);
    }
  }, [step]);

  return (
    <AnimatePresence mode="wait">
      {step === "instructions" && (
        <motion.div
          key="video-instructions"
          variants={stepVariants}
          initial="enter"
          animate="center"
          exit="exit"
