// â”€â”€â”€ Phone verification â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function PhoneVerification({ onComplete }: { onComplete: () => void }) {
  const [step, setStep] = useState<PhoneStep>("input");
  const [phone, setPhone] = useState("");
  const [code, setCode] = useState(["", "", "", "", "", ""]);
  const [timer, setTimer] = useState(45);
  const [canResend, setCanResend] = useState(false);
  const inputRefs = useRef<(HTMLInputElement | null)[]>([]);

  // Timer countdown
  useEffect(() => {
    if (step !== "code" || canResend) return;
    if (timer <= 0) {
      setCanResend(true);
      return;
    }
    const interval = setInterval(() => setTimer(t => t - 1), 1000);
    return () => clearInterval(interval);
  }, [step, timer, canResend]);

  // Auto-focus first digit input
  useEffect(() => {
    if (step === "code") {
      setTimeout(() => inputRefs.current[0]?.focus(), 400);
    }
  }, [step]);

  const handleDigitChange = useCallback((index: number, value: string) => {
    if (!/^\d*$/.test(value)) return;

    const newCode = [...code];
    newCode[index] = value.slice(-1);
    setCode(newCode);

    // Auto-advance
    if (value && index < 5) {
      inputRefs.current[index + 1]?.focus();
    }

    // Check if complete
    if (newCode.every(d => d !== "") && index === 5) {
      setTimeout(() => setStep("success"), 600);
    }
  }, [code]);

  const handleDigitKeyDown = useCallback((index: number, e: React.KeyboardEvent) => {
    if (e.key === "Backspace" && !code[index] && index > 0) {
      inputRefs.current[index - 1]?.focus();
    }
  }, [code]);

  const handleResend = () => {
    setTimer(45);
    setCanResend(false);
    setCode(["", "", "", "", "", ""]);
    inputRefs.current[0]?.focus();
  };

  return (
    <AnimatePresence mode="wait">
      {step === "input" && (
        <motion.div
          key="phone-input"
          variants={stepVariants}
          initial="enter"
          animate="center"
          exit="exit"
        >
          <p className="text-[13px] text-text-muted leading-relaxed mb-5">
            Un code SMS sera envoye a ton numero pour confirmer ton identite.
          </p>

          <label className="text-[10px] text-text-muted uppercase tracking-[0.2em] font-bold mb-2 block">
            Numero de telephone
          </label>
          <div className="flex gap-2 mb-6">
            <div className="flex items-center gap-1.5 bg-bg-card border border-border rounded-xl px-3 py-3 shrink-0">
              <span className="text-[14px]">ðŸ‡«ðŸ‡·</span>
              <span className="text-[14px] font-semibold text-text">+33</span>
            </div>
            <input
              type="tel"
              value={phone}
              onChange={e => setPhone(e.target.value.replace(/\D/g, "").slice(0, 10))}
              placeholder="6 12 34 56 78"
              className="flex-1 px-4 py-3 bg-bg-card border border-border rounded-xl text-[14px] text-text placeholder:text-text-muted outline-none focus:border-accent/50 transition-colors"
              aria-label="Numero de telephone"
              inputMode="tel"
            />
          </div>

          <motion.button
            onClick={() => {
              if (phone.length >= 9) {
                setStep("code");
              }
            }}
            disabled={phone.length < 9}
            className={`w-full py-3.5 rounded-full text-[14px] font-semibold tap-target transition-all ${
              phone.length >= 9
                ? "gradient-bg text-white shadow-glow"
                : "bg-border text-text-muted cursor-not-allowed"
            }`}
            whileTap={phone.length >= 9 ? micro.tapScale : undefined}
          >
            Envoyer le code
          </motion.button>
        </motion.div>
      )}

      {step === "code" && (
        <motion.div
          key="phone-code"
          variants={stepVariants}
          initial="enter"
          animate="center"
          exit="exit"
        >
          <p className="text-[13px] text-text-muted leading-relaxed mb-2">
            Code envoye au <span className="font-semibold text-text">+33 {phone}</span>
          </p>
          <button
            onClick={() => { setStep("input"); setCode(["", "", "", "", "", ""]); }}
            className="text-[12px] text-accent font-semibold mb-5"
          >
            Modifier le numero
          </button>

          {/* 6-digit code input */}
          <div className="flex gap-2.5 justify-center mb-6">
            {code.map((digit, i) => (
              <motion.div
                key={i}
                variants={digitVariants}
                initial="hidden"
                animate="visible"
                custom={i}
              >
                <input
                  ref={el => { inputRefs.current[i] = el; }}
                  type="text"
                  inputMode="numeric"
                  maxLength={1}
                  value={digit}
                  onChange={e => handleDigitChange(i, e.target.value)}
                  onKeyDown={e => handleDigitKeyDown(i, e)}
                  className={`w-12 h-14 text-center text-[20px] font-black rounded-xl border-2 outline-none transition-all ${
                    digit
                      ? "border-accent bg-accent/8 text-text"
                      : "border-border bg-bg-card text-text focus:border-accent/50"
                  }`}
                  aria-label={`Chiffre ${i + 1}`}
                />
              </motion.div>
            ))}
          </div>

          {/* Timer / resend */}
          <div className="text-center">
            {canResend ? (
              <button
                onClick={handleResend}
                className="text-[13px] text-accent font-semibold tap-target"
              >
                Renvoyer le code
              </button>
            ) : (
              <p className="text-[13px] text-text-muted">
                Renvoyer dans <span className="font-semibold text-text">{timer}s</span>
              </p>
            )}
          </div>
        </motion.div>
      )}

      {step === "success" && (
        <motion.div
          key="phone-success"
          variants={stepVariants}
          initial="enter"
          animate="center"
          exit="exit"
          className="flex flex-col items-center py-8"
        >
          <motion.div
            className="relative w-24 h-24 rounded-full gradient-bg flex items-center justify-center shadow-glow mb-5"
            variants={celebrationVariants}
            initial="hidden"
            animate="visible"
          >
            <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" aria-hidden="true">
              <motion.path
                d="M20 6L9 17l-5-5"
                strokeLinecap="round"
                strokeLinejoin="round"
                variants={checkmarkVariants}
                initial="hidden"
                animate="visible"
              />
            </svg>

            {[...Array(8)].map((_, i) => (
              <motion.div
                key={i}
                className="absolute w-2 h-2 rounded-full"
                style={{ background: i % 2 === 0 ? "#8B5CF6" : "#00FF88" }}
                initial={{ x: 0, y: 0, opacity: 1, scale: 1 }}
                animate={{
                  x: Math.cos((i / 8) * Math.PI * 2) * 60,
                  y: Math.sin((i / 8) * Math.PI * 2) * 60,
                  opacity: 0,
                  scale: 0,
                }}
                transition={{ duration: 0.8, delay: 0.3 + i * 0.05 }}
              />
            ))}
          </motion.div>

          <motion.p
            className="text-[18px] font-black text-text mb-1"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.5 }}
          >
            Telephone verifie !
          </motion.p>
          <motion.p
            className="text-[13px] text-text-muted mb-6"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.6 }}
          >
            Ton numero a ete confirme
          </motion.p>
          <motion.button
            onClick={onComplete}
            className="gradient-bg text-white px-8 py-3 rounded-full text-[14px] font-semibold shadow-glow tap-target"
            whileTap={micro.tapScale}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.7 }}
          >
            Continuer
          </motion.button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// â”€â”€â”€ Video liveness verification â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function VideoLivenessVerification({ onComplete }: { onComplete: () => void }) {
  const [step, setStep] = useState<VideoStep>("instructions");
  const [promptIndex, setPromptIndex] = useState(0);

  useEffect(() => {
    if (step === "smile" || step === "turn") {
      const idx = step === "smile" ? 0 : 1;
      setPromptIndex(idx);
      const timer = setTimeout(() => {
        if (idx === 0) {
          setStep("turn");
        } else {
          setStep("verifying");
        }
      }, VIDEO_PROMPTS[idx].duration);
      return () => clearTimeout(timer);
    }
    if (step === "verifying") {
      const timer = setTimeout(() => setStep("success"), 2000);
      return () => clearTimeout(timer);
    }
  }, [step]);

  return (
    <AnimatePresence mode="wait">
      {step === "instructions" && (
        <motion.div
          key="video-instructions"
          variants={stepVariants}
          initial="enter"
          animate="center"
          exit="exit"
        >
          <p className="text-[13px] text-text-muted leading-relaxed mb-5">
            Verification video en temps reel. Suis les instructions qui s&apos;affichent pour prouver que c&apos;est bien toi.
          </p>

