                      <p className={`text-[14px] font-bold ${isCompleted ? "text-safe" : "text-text"}`}>
                        {method.title}
                      </p>
                      {isSocial && !isCompleted && (
                        <span className="text-[8px] font-bold text-accent bg-accent/10 px-1.5 py-0.5 rounded-full uppercase tracking-wider shrink-0">
                          Bientot
                        </span>
                      )}
                    </div>
                    <p className="text-[11px] text-text-muted mt-0.5">
                      {isCompleted ? "Verification completee" : method.subtitle}
                    </p>
                  </div>

                  {/* Chevron */}
                  {!isCompleted && (
                    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" className="text-text-muted shrink-0" aria-hidden="true">
                      <path d="M9 18l6-6-6-6" />
                    </svg>
                  )}
                </motion.button>
              );
            })}
          </motion.div>
        )}

        {/* Info note */}
        {!activeMethod && (
          <motion.div
            className="mt-6 bg-bg-card border border-border rounded-2xl p-4"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ ...springs.heavy, delay: 0.5 }}
          >
            <div className="flex gap-3">
              <div className="w-8 h-8 rounded-lg bg-accent/8 flex items-center justify-center shrink-0">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-accent" aria-hidden="true">
                  <circle cx="12" cy="12" r="10" />
                  <path d="M12 16v-4m0-4h.01" />
                </svg>
              </div>
              <div>
                <p className="text-[12px] font-bold text-text mb-1">Pourquoi se verifier ?</p>
                <p className="text-[11px] text-text-muted leading-relaxed">
                  Les profils verifies recoivent 3x plus de matchs et inspirent confiance aux autres utilisateurs. Une seule methode suffit pour obtenir le badge.
                </p>
              </div>
            </div>
          </motion.div>
        )}
      </div>
    </div>
  );
}

