                backgroundImage: "linear-gradient(color-mix(in srgb, var(--color-bg) 30%, transparent) 1px, transparent 1px), linear-gradient(90deg, color-mix(in srgb, var(--color-bg) 30%, transparent) 1px, transparent 1px)",
