            </svg>

            {/* Sparkle particles */}
            {[...Array(8)].map((_, i) => (
              <motion.div
                key={i}
                className="absolute w-2 h-2 rounded-full"
                style={{ background: i % 2 === 0 ? "#3B82F6" : "var(--color-accent-2)" /* LinkedIn brand + CeSoir green */ }}
