      )}

      {step === "verifying" && (
        <motion.div
          key="video-verifying"
          variants={stepVariants}
          initial="enter"
          animate="center"
          exit="exit"
          className="flex flex-col items-center py-12"
        >
          <motion.div
            className="w-16 h-16 rounded-full border-2 border-t-accent border-r-transparent border-b-transparent border-l-transparent mb-4"
            animate={{ rotate: 360 }}
            transition={{ repeat: Infinity, duration: 1, ease: "linear" }}
          />
          <p className="text-[15px] font-bold text-text mb-1">Analyse en cours...</p>
          <p className="text-[12px] text-text-muted">Verification de la vivacite</p>
        </motion.div>
      )}

      {step === "success" && (
        <motion.div
          key="video-success"
          variants={stepVariants}
          initial="enter"
          animate="center"
          exit="exit"
          className="flex flex-col items-center py-8"
        >
          <motion.div
            className="relative w-24 h-24 rounded-full gradient-bg flex items-center justify-center shadow-glow mb-5"
            initial={{ scale: 0 }}
            animate={{ scale: [0, 1.35, 0.9, 1.1, 1] }}
            transition={{ duration: 0.7, times: [0, 0.3, 0.5, 0.7, 1] }}
          >
            {/* Blue checkmark */}
            <svg width="40" height="40" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="12" cy="12" r="10" fill="#3B82F6" /* LinkedIn brand blue â€” intentional */ />
              <motion.path
                d="M8 12l3 3 5-5"
                stroke="white"
                strokeWidth="2.5"
                strokeLinecap="round"
                strokeLinejoin="round"
                fill="none"
                initial={{ pathLength: 0, opacity: 0 }}
                animate={{ pathLength: 1, opacity: 1 }}
                transition={{ duration: 0.6, delay: 0.3, ease: [0.16, 1, 0.3, 1] }}
              />
            </svg>

            {/* Sparkle particles */}
            {[...Array(8)].map((_, i) => (
              <motion.div
                key={i}
                className="absolute w-2 h-2 rounded-full"
                style={{ background: i % 2 === 0 ? "#3B82F6" : "var(--color-accent-2)" /* LinkedIn brand + CeSoir green */ }}
                initial={{ x: 0, y: 0, opacity: 1, scale: 1 }}
                animate={{
                  x: Math.cos((i / 8) * Math.PI * 2) * 60,
                  y: Math.sin((i / 8) * Math.PI * 2) * 60,
                  opacity: 0,
                  scale: 0,
                }}
                transition={{ duration: 0.8, delay: 0.3 + i * 0.05 }}
              />
            ))}
          </motion.div>

          <motion.div
            className="flex items-center gap-2 mb-1"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.5 }}
          >
            <p className="text-[18px] font-black text-text">Video Verifie</p>
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <circle cx="12" cy="12" r="10" fill="#3B82F6" /* LinkedIn brand blue â€” intentional */ />
              <path d="M8 12l3 3 5-5" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
          </motion.div>
          <motion.p
            className="text-[13px] text-text-muted mb-6"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.6 }}
          >
            Badge coche bleue attribue a ton profil
          </motion.p>
          <motion.button
            onClick={onComplete}
            className="gradient-bg text-white px-8 py-3 rounded-full text-[14px] font-semibold shadow-glow tap-target"
            whileTap={micro.tapScale}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.7 }}
          >
            Continuer
          </motion.button>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

