                  whileTap={{ scale: 0.92 }}
                  transition={springs.snap}
                  className="flex-shrink-0 px-3.5 py-2 rounded-xl text-xs font-bold text-white"
                  style={{ background: "linear-gradient(135deg, var(--color-accent), var(--color-accent-2))" }}
