// â”€â”€ Pill selector â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

function PillSelector<T extends string>({
  options,
  value,
  onChange,
}: {
  options: { value: T; label: string }[];
  value: T;
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex gap-2">
      {options.map((opt) => {
        const active = value === opt.value;
        return (
          <button
            key={opt.value}
            onClick={() => onChange(opt.value)}
            aria-pressed={active}
            className={`flex-1 py-2.5 rounded-xl text-[12px] font-medium transition-colors tap-target ${
              active
                ? "bg-accent text-white"
                : "border border-border text-text-muted hover:border-accent/30"
            }`}
          >
            {opt.label}
          </button>
        );
      })}
    </div>
  );
}

