          <div className="w-full h-full rounded-full bg-bg flex items-center justify-center text-[16px] font-black text-accent">
            {name.charAt(0).toUpperCase()}
          </div>
        )}
      </div>
      <div>
        <h1 className="text-[18px] font-bold text-text">
          Planifier avec {name}
        </h1>
        <p className="text-[11px] text-text-muted">Organisez votre soiree</p>
      </div>
    </div>
  );
}

// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Main page
// â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export default function DatePlannerPage() {
  const params = useParams();
  const router = useRouter();
  const matchId = params.matchId as string;

  const { proposePlan } = usePlans();

  // State
  const [step, setStep] = useState<Step>(1);
  const [selectedTime, setSelectedTime] = useState<string | null>(null);
  const [selectedActivity, setSelectedActivity] = useState<string | null>(null);
  const [selectedVenueId, setSelectedVenueId] = useState<string | null>(null);
  const [selectedVenue, setSelectedVenue] = useState<Venue | null>(null);
  const [sent, setSent] = useState(false);

  // Venue suggestions based on selected activity
  const venues = useMemo(() => {
    if (!selectedActivity) return [];
    return suggestVenuesByActivity(selectedActivity, USER_LAT, USER_LNG, 4);
  }, [selectedActivity]);

  // Navigation
  const canAdvance =
    (step === 1 && selectedTime) ||
    (step === 2 && selectedActivity) ||
    (step === 3 && selectedVenue) ||
    step === 4;

  const goNext = useCallback(() => {
    if (step < 4) setStep((s) => (s + 1) as Step);
  }, [step]);

  const goBack = useCallback(() => {
    if (step > 1) setStep((s) => (s - 1) as Step);
  }, [step]);

  const handleSelectVenue = useCallback((venue: Venue) => {
    setSelectedVenueId(venue.id);
    setSelectedVenue(venue);
  }, []);

  const handleProposeVenue = useCallback(
    (venue: Venue) => {
      setSelectedVenue(venue);
      setSelectedVenueId(venue.id);
      goNext();
    },
    [goNext],
  );

  const handleSend = useCallback(async () => {
    setSent(true);

    // Map selectedTime ("19h", "flexible", etc.) to an ISO datetime
    const when = (() => {
      const d = new Date();
      if (selectedTime && selectedTime !== "flexible") {
        const match = selectedTime.match(/(\d{1,2})h/);
        if (match) {
          d.setHours(parseInt(match[1], 10), 0, 0, 0);
          if (d.getTime() < Date.now()) d.setDate(d.getDate() + 1);
        }
      } else {
        d.setHours(20, 0, 0, 0);
      }
      return d.toISOString();
    })();

    const whereText = selectedVenue ? `${selectedVenue.name} - ${selectedVenue.address}` : "";

    // Fire-and-forget persistence; UI proceeds regardless to preserve UX.
    void proposePlan({
      partnerId: matchId,
      whenDate: when,
      what: selectedActivity ?? "",
      whereText,
    });

    setTimeout(() => {
      router.push(`/chat/${matchId}`);
    }, 2000);
  }, [matchId, router, proposePlan, selectedTime, selectedActivity, selectedVenue]);

  // Activity label lookup
  const activityLabel =
    ACTIVITIES.find((a) => a.key === selectedActivity)?.label ?? "";
  const activityEmoji =
    ACTIVITIES.find((a) => a.key === selectedActivity)?.emoji ?? "";

  return (
    <div className="min-h-screen bg-bg relative">
      <PageHeader
        onBack={step > 1 ? goBack : () => router.back()}
        hideTitle
        leftSlot={<MatchHeader name={MOCK_MATCH.name} avatar={MOCK_MATCH.avatar} />}
        slotBelowTitle={<ProgressDots current={step} />}
      />

      {/* Step content */}
      <main className="px-5 pb-32 pt-6">
        <AnimatePresence mode="wait">
          {/* â”€â”€ Step 1: Quand? â”€â”€ */}
          {step === 1 && (
            <motion.div
              key="step-1"
              variants={stepVariants}
              initial="enter"
              animate="center"
              exit="exit"
            >
              <h2 className="text-[22px] font-bold text-text mb-1">
                {"\u{1F552}"} Quand ?
              </h2>
              <p className="text-[13px] text-text-muted mb-6">
                Choisissez l&apos;heure pour ce soir
              </p>

              <div className="grid grid-cols-3 gap-3">
                {TIME_SLOTS.map((slot, i) => {
                  const isActive = selectedTime === slot.value;
                  return (
                    <motion.button
                      key={slot.value}
                      custom={i}
                      variants={gridItemVariants}
                      initial="hidden"
                      animate="visible"
                      onClick={() => setSelectedTime(slot.value)}
                      whileTap={{ scale: 0.92 }}
                      className={`flex flex-col items-center gap-2 p-4 rounded-2xl border transition-all ${
                        isActive
                          ? "border-accent bg-accent/10 shadow-glow"
                          : "border-border bg-bg-card hover:border-accent/30"
                      }`}
                    >
                      <span className="text-[24px]">{slot.emoji}</span>
                      <span
                        className={`text-[14px] font-semibold ${
                          isActive ? "text-accent" : "text-text"
                        }`}
                      >
                        {slot.label}
                      </span>
                      {isActive && (
                        <motion.div
                          layoutId="time-check"
                          className="w-4 h-4 rounded-full gradient-bg flex items-center justify-center"
                          transition={springs.elastic}
                        >
                          <span className="text-white text-[8px] font-bold">
                            {"\u2713"}
                          </span>
                        </motion.div>
                      )}
                    </motion.button>
                  );
                })}
              </div>
            </motion.div>
          )}

          {/* â”€â”€ Step 2: Quoi? â”€â”€ */}
          {step === 2 && (
            <motion.div
              key="step-2"
              variants={stepVariants}
              initial="enter"
              animate="center"
              exit="exit"
            >
              <h2 className="text-[22px] font-bold text-text mb-1">
                {"\uD83C\uDFAF"} Quoi ?
              </h2>
              <p className="text-[13px] text-text-muted mb-6">
                Qu&apos;est-ce qui vous ferait plaisir ?
              </p>

              <div className="grid grid-cols-2 gap-3">
                {ACTIVITIES.map((act, i) => {
                  const isActive = selectedActivity === act.key;
                  return (
                    <motion.button
                      key={act.key}
                      custom={i}
                      variants={activityVariants}
                      initial="hidden"
                      animate="visible"
                      onClick={() => {
                        setSelectedActivity(act.key);
                        setSelectedVenueId(null);
                        setSelectedVenue(null);
                      }}
                      whileTap={{ scale: 0.92 }}
                      className={`flex items-center gap-3 p-4 rounded-2xl border transition-all ${
                        isActive
                          ? "border-accent bg-accent/10 shadow-glow"
                          : "border-border bg-bg-card hover:border-accent/30"
                      }`}
                    >
                      <span className="text-[28px]">{act.emoji}</span>
                      <span
                        className={`text-[14px] font-semibold ${
                          isActive ? "text-accent" : "text-text"
                        }`}
                      >
                        {act.label}
                      </span>
                      {isActive && (
                        <motion.span
                          initial={{ scale: 0 }}
                          animate={{ scale: 1 }}
                          transition={springs.elastic}
                          className="ml-auto w-5 h-5 rounded-full gradient-bg flex items-center justify-center text-white text-[9px] font-bold shrink-0"
                        >
                          {"\u2713"}
                        </motion.span>
                      )}
                    </motion.button>
                  );
                })}
              </div>
            </motion.div>
          )}

          {/* â”€â”€ Step 3: Ou? â”€â”€ */}
          {step === 3 && (
            <motion.div
              key="step-3"
              variants={stepVariants}
              initial="enter"
              animate="center"
              exit="exit"
            >
              <h2 className="text-[22px] font-bold text-text mb-1">
                {"\uD83D\uDCCD"} Ou ?
              </h2>
              <p className="text-[13px] text-text-muted mb-6">
                Suggestions {activityLabel.toLowerCase()} pres de vous
              </p>

              {venues.length > 0 ? (
                <VenuePicker
                  venues={venues}
                  selectedId={selectedVenueId}
                  onSelect={handleSelectVenue}
                  onPropose={handleProposeVenue}
                />
              ) : (
                <EmptyState
                  emoji={"\uD83D\uDCCD"}
                  title="Aucun lieu trouve pour cette activite"
                  subtitle="Essaie une autre activite ou elargis la recherche."
                />
              )}
            </motion.div>
          )}

          {/* â”€â”€ Step 4: Confirmation â”€â”€ */}
          {step === 4 && (
            <motion.div
              key="step-4"
              variants={stepVariants}
              initial="enter"
              animate="center"
              exit="exit"
              className="flex flex-col items-center"
            >
              <h2 className="text-[22px] font-bold text-text mb-1 text-center">
                {"\u2728"} Confirmation
              </h2>
              <p className="text-[13px] text-text-muted mb-6 text-center">
                Verifiez les details avant d&apos;envoyer
              </p>

              {/* Summary card */}
              <motion.div
                variants={confirmVariants}
                initial="hidden"
                animate="visible"
                className="w-full max-w-sm rounded-2xl border border-accent/30 bg-bg-card p-6 relative overflow-hidden"
                style={{
                  boxShadow:
                    "0 0 40px rgba(139,92,246,0.15), 0 0 80px rgba(139,92,246,0.05)",
                }}
              >
                {/* Glow effect */}
                <motion.div
                  className="absolute inset-0 rounded-2xl pointer-events-none"
                  animate={achievementVariants.glow.pulse}
                />

                <div className="relative z-10 space-y-4">
                  {/* Match header in card */}
                  <div className="flex items-center gap-3 pb-4 border-b border-border">
                    <div className="w-12 h-12 rounded-full gradient-bg p-[2px]">
                      <div className="w-full h-full rounded-full bg-bg flex items-center justify-center text-[18px] font-black text-accent">
                        {MOCK_MATCH.name.charAt(0)}
                      </div>
                    </div>
                    <div>
                      <p className="text-[15px] font-bold text-text">
                        Soiree avec {MOCK_MATCH.name}
                      </p>
                      <p className="text-[11px] text-text-muted">Ce soir</p>
                    </div>
                  </div>

                  {/* Details rows */}
                  <div className="space-y-3">
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-accent/10 flex items-center justify-center text-[16px]">
                        {"\u{1F552}"}
                      </span>
                      <div>
                        <p className="text-[10px] text-text-muted uppercase tracking-wide font-semibold">
                          Heure
                        </p>
                        <p className="text-[14px] font-bold text-text">
                          {selectedTime === "flexible"
                            ? "Flexible"
                            : selectedTime}
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 rounded-lg bg-accent/10 flex items-center justify-center text-[16px]">
                        {activityEmoji}
                      </span>
                      <div>
                        <p className="text-[10px] text-text-muted uppercase tracking-wide font-semibold">
                          Activite
                        </p>
                        <p className="text-[14px] font-bold text-text">
                          {activityLabel}
                        </p>
                      </div>
                    </div>

                    {selectedVenue && (
                      <div className="flex items-center gap-3">
                        <span className="w-8 h-8 rounded-lg bg-accent/10 flex items-center justify-center text-[16px]">
                          {"\uD83D\uDCCD"}
                        </span>
                        <div>
                          <p className="text-[10px] text-text-muted uppercase tracking-wide font-semibold">
                            Lieu
                          </p>
                          <p className="text-[14px] font-bold text-text">
                            {selectedVenue.name}
                          </p>
                          <p className="text-[11px] text-text-muted">
                            {selectedVenue.address} &middot;{" "}
                            {formatPrice(selectedVenue.priceRange)}
                          </p>
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              </motion.div>

              {/* Send button */}
              <motion.button
                onClick={handleSend}
                disabled={sent}
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ ...springs.elastic, delay: 0.4 }}
                whileHover={{ y: -2 }}
                whileTap={{ scale: 0.95 }}
                className={`mt-6 w-full max-w-sm py-4 rounded-2xl text-center text-[15px] font-bold shadow-glow transition-all ${
                  sent
                    ? "bg-safe text-white"
                    : "gradient-bg text-white"
                }`}
              >
                {sent ? (
                  <motion.span
                    initial={{ scale: 0 }}
                    animate={{ scale: 1 }}
                    transition={springs.elastic}
                    className="inline-flex items-center gap-2"
                  >
                    {"\u2713"} Envoye a {MOCK_MATCH.name} !
                  </motion.span>
                ) : (
                  <>Envoyer a {MOCK_MATCH.name}</>
                )}
              </motion.button>
            </motion.div>
          )}
        </AnimatePresence>
      </main>

      {/* Bottom navigation â€” Next/Back */}
      {step < 4 && (
        <div className="fixed bottom-0 left-0 right-0 z-50 bg-bg/95 backdrop-blur-md border-t border-border px-5 py-4 safe-area-bottom">
          <div className="flex gap-3 max-w-sm mx-auto">
            {step > 1 && (
              <motion.button
                onClick={goBack}
                whileTap={{ scale: 0.95 }}
                className="flex-1 py-3.5 rounded-2xl border border-border text-[14px] font-semibold text-text bg-bg-card"
              >
                Retour
              </motion.button>
            )}
            <motion.button
              onClick={goNext}
              disabled={!canAdvance}
              whileHover={canAdvance ? { y: -2 } : undefined}
              whileTap={canAdvance ? { scale: 0.95 } : undefined}
              transition={springs.snap}
              className={`flex-1 py-3.5 rounded-2xl text-[14px] font-bold transition-all ${
                canAdvance
                  ? "gradient-bg text-white shadow-glow"
                  : "bg-border text-text-muted cursor-not-allowed"
              }`}
            >
              Suivant
            </motion.button>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import { useState, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import { motion, AnimatePresence, useAnimationControls } from "motion/react";
import { springs, micro } from "@/lib/motion-design";
import { useAuth } from "@/context/AuthContext";
import { useProfile } from "@/lib/useProfile";
import PhotoUpload from "@/components/app/PhotoUpload";
import { Magnetic } from "@/components/motion/Magnetic";
import PageHeader from "@/components/ui/PageHeader";

const BIO_MAX = 200;

const GENDERS = [
  { v: "homme", l: "Homme" },
  { v: "femme", l: "Femme" },
  { v: "autre", l: "Autre" },
] as const;

const LOOKING_FOR = [
  { v: "hommes", l: "Hommes" },
  { v: "femmes", l: "Femmes" },
  { v: "tous", l: "Tous" },
] as const;

export default function EditProfilePage() {
  const router = useRouter();
  const { user } = useAuth();
  const { profile, loading, updateProfile } = useProfile(user?.id);

  const [name, setName] = useState("");
  const [age, setAge] = useState("");
  const [bio, setBio] = useState("");
  const [gender, setGender] = useState("");
  const [lookingFor, setLookingFor] = useState("");
  const [city, setCity] = useState("Paris");
  const [saving, setSaving] = useState(false);
  const [toast, setToast] = useState(false);

  const btnControls = useAnimationControls();
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (profile) {
      setName(profile.name || "");
      setAge(String(profile.age || ""));
      setBio(profile.bio || "");
      setGender(profile.gender || "");
      setLookingFor(profile.looking_for || "");
      setCity(profile.city || "Paris");
    }
  }, [profile]);

  async function handleSave(e: React.FormEvent) {
    e.preventDefault();
    setSaving(true);

    const ok = await updateProfile({
      name,
      age: parseInt(age),
      bio,
      gender: gender as "homme" | "femme" | "autre",
      looking_for: lookingFor as "hommes" | "femmes" | "tous",
      city,
    });

    setSaving(false);

    if (ok) {
      // Success pop on button
      btnControls.start(micro.successPop);

      // Show toast
      setToast(true);
      setTimeout(() => {
        setToast(false);
        router.back();
      }, 1500);
    }
  }

  if (loading)
    return (
      <div className="min-h-screen bg-bg flex items-center justify-center">
        <motion.span
          className="text-3xl text-accent"
          animate={{ scale: [1, 1.2, 1], opacity: [0.5, 1, 0.5] }}
          transition={{ duration: 1.5, repeat: Infinity }}
        >
          â˜¾
        </motion.span>
      </div>
    );

  // Stagger helper: each field delays by 0.06s
  const fieldMotion = (i: number) => ({
    initial: { opacity: 0, y: 20 },
    animate: { opacity: 1, y: 0 },
    transition: { ...springs.heavy, delay: i * 0.06 },
  });

  return (
    <div className="min-h-screen bg-bg">
      <PageHeader
        title="Modifier mon profil"
        onBack={() => router.back()}
        backIconVariant="close"
        magneticBack
        backLabel="Fermer"
      />

      <form
        ref={formRef}
        onSubmit={handleSave}
        className="px-5 py-6 max-w-sm mx-auto space-y-5"
      >
        {/* --- Photo --- */}
        <motion.div className="flex justify-center" {...fieldMotion(0)}>
          {user && (
            <PhotoUpload
              userId={user.id}
              currentAvatarUrl={profile?.avatar_url}
              onUploadComplete={() => {}}
              variant="compact"
              fallbackLetter={name?.charAt(0)?.toUpperCase() || "?"}
            />
          )}
        </motion.div>

        {/* --- Name --- */}
        <motion.div {...fieldMotion(1)}>
          <label
            htmlFor="edit-name"
            className="block text-[11px] font-semibold text-text-muted uppercase tracking-wider mb-1.5"
          >
            Prenom
          </label>
          <input
            id="edit-name"
            type="text"
            value={name}
            onChange={(e) => setName(e.target.value)}
            required
            className="w-full px-4 py-3 bg-bg border border-border rounded-xl text-sm text-text focus:border-accent/40 outline-none transition-colors"
          />
        </motion.div>

        {/* --- Age --- */}
        <motion.div {...fieldMotion(2)}>
          <label
            htmlFor="edit-age"
            className="block text-[11px] font-semibold text-text-muted uppercase tracking-wider mb-1.5"
          >
            Age
          </label>
          <input
            id="edit-age"
            type="number"
            min={18}
            max={99}
            value={age}
            onChange={(e) => setAge(e.target.value)}
            required
            className="w-full px-4 py-3 bg-bg border border-border rounded-xl text-sm text-text focus:border-accent/40 outline-none transition-colors"
          />
        </motion.div>

        {/* --- Bio --- */}
        <motion.div {...fieldMotion(3)}>
          <label
            htmlFor="edit-bio"
            className="block text-[11px] font-semibold text-text-muted uppercase tracking-wider mb-1.5"
          >
            Bio
          </label>
          <textarea
            id="edit-bio"
            rows={4}
            maxLength={BIO_MAX}
            value={bio}
            onChange={(e) => setBio(e.target.value.slice(0, BIO_MAX))}
            placeholder="Parle de toi..."
            className="w-full px-4 py-3 bg-bg border border-border rounded-xl text-sm text-text resize-none focus:border-accent/40 outline-none transition-colors"
          />
          <p
            className={`text-[10px] mt-1 font-medium transition-colors ${
