            Je suis
          </legend>
          <div className="grid grid-cols-3 gap-2">
            {GENDERS.map((g) => (
              <motion.button
                key={g.v}
                type="button"
                onClick={() => setGender(g.v)}
                aria-pressed={gender === g.v}
